                        # satisfied.
                        for other_operation in self.generated_operations[dep[0]]:
                            if self.check_dependency(other_operation, dep):
                                deps_satisfied = False
                                break
                        if not deps_satisfied:
                            break
                        else:
                            if self.migrations.get(dep[0], None):
