                    self.migrations.setdefault(app_label, []).append(instance)
                    chop_mode = False
                else:
                    self.generated_operations[app_label] = chopped + self.generated_operations[app_label]
        new_num_ops = sum(len(x) for x in self.generated_operations.values())
